const parentRunId = $input.first().json.run_id || Date.now().toString();
const runId = `IPS-${new Date().toISOString().replace(/[:.]/g,'-')}`;
return [{ json: {
  run_id: runId,
  parent_run_id: parentRunId,
  week: new Date().toISOString().substring(0,7),
  started_at: new Date().toISOString()
} }];

const sources = $input.all().map(item => item.json);

const now = new Date();
const jan1 = new Date(now.getFullYear(), 0, 1);
const dayOfYear = Math.ceil((now - jan1) / 86400000);
const isoWeek = Math.ceil(dayOfYear / 7);

const FORCE_ALL_PRIORITIES = false;
const NARROW_TEST_LANE = null;

let activePriorities = ['P1'];
if (FORCE_ALL_PRIORITIES) {
  activePriorities = ['P1', 'P2', 'P3'];
} else {
  if (isoWeek % 2 === 0) activePriorities.push('P2');
  if (isoWeek % 4 === 0) activePriorities.push('P3');
}

let filtered = sources.filter(s => activePriorities.includes(s.priority));

if (NARROW_TEST_LANE) {
  filtered = filtered.filter(s => s.capability_area === NARROW_TEST_LANE);
}

let runId, week;
try {
  const ctx = $('Set Run Context').first().json;
  runId = ctx.run_id;
  week = ctx.week;
} catch (e) {
  runId = `RUN-${now.toISOString().slice(0, 10)}-${Math.random().toString(36).slice(2, 7)}`;
  week = `${now.getFullYear()}-W${String(isoWeek).padStart(2, '0')}`;
}

return filtered.map(s => ({
  json: {
    source_id:       s.source_id,
    product_name:    s.product_name,
    capability_area: s.capability_area,
    source_type:     s.source_type,
    capability_tag:  s.capability_tag,
    source_role:     s.source_role,
    priority:        s.priority,
    url:             s.url,
    run_id:          runId,
    week:            week
  }
}));

const d = $input.item.json;
const content = d.data || d.body || '';
const contentLength = typeof content === 'string' ? content.length : 0;
return { json: { ...d, content_preview: content.substring(0, 6000), content_length: contentLength } };

const item = $input.item.json;

if (!item.content || item.error) {
  return { json: { ...item, _no_caps: true, _capabilities: [] } };
}

const rawText = item.content?.[0]?.text || '';

let capabilities = [];
try {
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  capabilities = JSON.parse(cleaned);
  if (!Array.isArray(capabilities)) capabilities = [];
} catch (e) {
  capabilities = [];
}

if (capabilities.length === 0) {
  return { json: { ...item, _no_caps: true, _capabilities: [] } };
}

return { json: { ...item, _no_caps: false, _capabilities: capabilities } };
